/* builds a translator for a language code; unknown strings are returned unchanged */
export function makeTranslator(code) {
  const idx = { ta: 1, hi: 2 }[code];
  if (!idx) return s => s;
  const exact = new Map();
  for (const r of R) exact.set(r[0], r[idx]);
  const rules = P[code];
  const t = s => {
    const key = s.trim().replace(/\s+/g, ' ');
    if (!/[A-Za-z]{2}/.test(key)) return s;
    let out = exact.get(key);
    if (out === undefined) for (const [re, fn] of rules) { const m = re.exec(key); if (m) { const v = fn(t, ...m.slice(1)); if (v != null) { out = v; break; } } }
    return out === undefined ? s : s.replace(s.trim(), out);
  };
  return t;
}
export const COVERAGE_ROWS = R.length;
export const LANG_ROWS = R;
